import {DEFAULT_CAMERA,clampPitch,render3D,metricScaleBar,droneMapLabel} from './map3d.js';
import {aircraftPaint} from './map_status.js';
export const esc = value => String(value ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const finite = value => typeof value === 'number' && Number.isFinite(value);
export const num = (value,digits=2) => finite(value) ? value.toLocaleString('ko-KR',{maximumFractionDigits:digits}) : '—';
export const time = value => finite(value) ? `${String(Math.floor(value/60)).padStart(2,'0')}:${(value%60).toFixed(1).padStart(4,'0')}` : '—';
export const fmt = (value,unit='',digits=2) => typeof value==='boolean' ? (value?'예':'아니오') : !finite(value) ? '—' : unit==='ratio' ? `${num(value*100,digits)}%` : unit==='boolean' ? (value?'예':'아니오') : `${num(value,digits)}${unit&& !['count','unknown','reward'].includes(unit)?' '+unit:''}`;
export function before(rows,t,key='sample_time_s'){let lo=0,hi=rows.length-1,index=-1;while(lo<=hi){const m=(lo+hi)>>1;if(Number(rows[m][key])<=t+1e-8){index=m;lo=m+1}else hi=m-1}return index<0?null:rows[index]}
export function positionAt(rows,t){const a=before(rows,t);if(!a)return {uavs:[],interpolated:false};const i=rows.indexOf(a),b=rows[i+1];if(!b||t<=a.sample_time_s+1e-8)return {...a,interpolated:false};const k=(t-a.sample_time_s)/(b.sample_time_s-a.sample_time_s);if(k<0||k>1)return {...a,interpolated:false};const dest=new Map((b.uavs||[]).map(n=>[n.id,n]));return {sample_time_s:t,from_s:a.sample_time_s,to_s:b.sample_time_s,interpolated:true,uavs:(a.uavs||[]).map(n=>{const m=dest.get(n.id);return m?{...n,x:n.x+(m.x-n.x)*k,y:n.y+(m.y-n.y)*k,z:finite(n.z)&&finite(m.z)?n.z+(m.z-n.z)*k:n.z}:n})}}
export function intervalAt(rows,t){const a=before(rows,t,'interval_start_s');return a&&t<a.interval_end_s-1e-8?a:null}
export function packetAt(rows,t){return before(rows,t,'available_at_s')}
export function completedDecisionAt(rows,t){for(let i=rows.length-1;i>=0;i--){const d=rows[i],actions=d.actions||[];if(d.decision_time_s>t||!actions.length)continue;if(actions.every(a=>finite(a.actual_available_at_s??a.interval_end_s)&&(a.actual_available_at_s??a.interval_end_s)<=t))return d}return null}
export function chartSVG(points,{unit='',selected=0,window=null,color='#0d938d',height=150,events=[],label='',ticks=5,fill=true,min=null,max=null}={}){const valid=points.filter(p=>finite(p.t)&&finite(p.v));const x0=window?.[0]??valid[0]?.t??0,x1=window?.[1]??valid.at(-1)?.t??1,w=720,h=height,L=48,R=18,T=14,B=27;let y0=min??Math.min(...valid.map(p=>p.v),0),y1=max??Math.max(...valid.map(p=>p.v),1);if(!Number.isFinite(y0))y0=0;if(!Number.isFinite(y1))y1=1;if(y1===y0)y1=y0+1;const X=t=>L+(t-x0)/(x1-x0||1)*(w-L-R),Y=v=>h-B-(v-y0)/(y1-y0)*(h-T-B);let path='',open=false;for(const p of points){if(p.t<x0||p.t>x1)continue;if(!finite(p.v)){open=false;continue}path+=`${open?'L':'M'}${X(p.t).toFixed(2)},${Y(p.v).toFixed(2)} `;open=true}let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(label)} 시간 그래프"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="${color}" stop-opacity=".14"/><stop offset="1" stop-color="${color}" stop-opacity=".01"/></linearGradient></defs>`;for(let i=0;i<4;i++){if(unit==='boolean'&&i!==0&&i!==3)continue;const v=y0+(y1-y0)*i/3,y=Y(v);svg+=`<path d="M${L} ${y}H${w-R}" stroke="#e8eef2" stroke-dasharray="3 4"/><text x="${L-8}" y="${y+3}" text-anchor="end" fill="#8d9cab" font-size="8">${esc(fmt(v,unit,1))}</text>`}for(let i=0;i<ticks;i++){const t=x0+(x1-x0)*i/(ticks-1);svg+=`<text x="${X(t)}" y="${h-5}" text-anchor="middle" fill="#8d9cab" font-size="8">${esc(time(t))}</text>`}for(const e of events){const end=e.end_s??(e.temporal_kind==='instant'?e.start_s+.5:x1);if(e.start_s>x1||end<x0)continue;const a=X(Math.max(e.start_s,x0)),b=X(Math.min(end,x1));svg+=`<rect x="${a}" y="${T}" width="${Math.max(1,b-a)}" height="${h-T-B}" fill="#e86c74" opacity=".08"/>`}if(path)svg+=`<path d="${path}" fill="none" stroke="${color}" stroke-width="1.7" stroke-linejoin="round"/>`;if(selected>=x0&&selected<=x1){const x=X(selected);svg+=`<path d="M${x} ${T}V${h-B}" stroke="#193b5a" stroke-width="1" stroke-dasharray="4 3"/><circle cx="${x}" cy="${T}" r="3" fill="#193b5a"/>`}if(!valid.length)svg+=`<text x="${w/2}" y="${h/2}" text-anchor="middle" fill="#91a0ae" font-size="11">이 구간에 유효한 관측이 없습니다</text>`;return svg+'</svg>'}
function polygons(g){if(!g)return[];if(g.type==='Polygon')return[g.coordinates];if(g.type==='MultiPolygon')return g.coordinates;if(g.type==='Feature')return polygons(g.geometry);if(Array.isArray(g)&&Array.isArray(g[0]))return typeof g[0][0]==='number'?[[g]]:[g];return[]}
export class MapRenderer{
 constructor(canvas,onSelect){
 this.canvas=canvas;this.ctx=canvas.getContext('2d');this.onSelect=onSelect;this.hit=[];this.linkHit=[];this.zoom=1;this.pan=[0,0];this.data=null;this.drag=null;this.suppressClick=false;this.viewMode='3d';this.camera={...DEFAULT_CAMERA};this.projection=null;
 new ResizeObserver(()=>this.draw()).observe(canvas);
 canvas.addEventListener('wheel',e=>{e.preventDefault();const box=canvas.getBoundingClientRect(),old=this.zoom,next=Math.max(.6,Math.min(8,old*(e.deltaY>0?.9:1.1))),ratio=next/old;const x=e.clientX-box.left-box.width/2,y=e.clientY-box.top-box.height/2;this.pan=[x-(x-this.pan[0])*ratio,y-(y-this.pan[1])*ratio];this.zoom=next;this.draw()},{passive:false});
 canvas.addEventListener('pointerdown',e=>{if(![0,1,2].includes(e.button))return;this.suppressClick=false;this.drag={x:e.clientX,y:e.clientY,pan:[...this.pan],camera:{...this.camera},rotate:this.viewMode==='3d'&&(e.shiftKey||e.button===2),id:e.pointerId,moved:false};canvas.setPointerCapture(e.pointerId);if(e.button!==0)e.preventDefault()});
 canvas.addEventListener('contextmenu',e=>e.preventDefault());
 canvas.addEventListener('pointermove',event=>{
  if(this.drag){canvas.title='';return;}
  const box=canvas.getBoundingClientRect();
  const point=this.hit.find(node=>Math.hypot(node.x-event.clientX+box.left,node.y-event.clientY+box.top)<16);
  const paint=point&&aircraftPaint(this.data?.communication,point.id);
  canvas.title=paint?(paint.label||point.id)+' · '+paint.description:'';
 });
 canvas.addEventListener('pointerleave',()=>{canvas.title='';});
 canvas.addEventListener('pointermove',e=>{const d=this.drag;if(!d||d.id!==e.pointerId)return;const dx=e.clientX-d.x,dy=e.clientY-d.y;if(!d.moved&&Math.hypot(dx,dy)<4)return;d.moved=true;if(d.rotate){this.camera={yaw:d.camera.yaw+dx*.008,pitch:clampPitch(d.camera.pitch+dy*.006)}}else this.pan=[d.pan[0]+dx,d.pan[1]+dy];canvas.classList.add('dragging');this.draw()});
 const release=e=>{if(!this.drag||this.drag.id!==e.pointerId)return;this.suppressClick=this.drag.moved||e.type==='pointercancel';this.drag=null;canvas.classList.remove('dragging');if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId)};
 canvas.addEventListener('pointerup',release);canvas.addEventListener('pointercancel',release);canvas.addEventListener('lostpointercapture',e=>{if(this.drag?.id===e.pointerId){this.suppressClick=true;this.drag=null;canvas.classList.remove('dragging')}});
 canvas.addEventListener('click',e=>{if(this.suppressClick){this.suppressClick=false;return}if(e.button!==0)return;const box=canvas.getBoundingClientRect(),p=[e.clientX-box.left,e.clientY-box.top];const n=this.hit.find(n=>Math.hypot(n.x-p[0],n.y-p[1])<16);if(n){this.onSelect({node:n.id});return}const l=this.linkHit.map(l=>({...l,d:segmentDistance(p,l.a,l.b)})).filter(l=>l.d<7).sort((a,b)=>a.d-b.d)[0];if(l)this.onSelect({node:l.source,peer:l.target,link:l.id})});
 canvas.addEventListener('keydown',e=>{if(e.key==='Home'){this.reset();e.preventDefault()}});
 }
 setViewMode(mode){if(!['2d','3d'].includes(mode))throw new Error('Unsupported map view mode');if(this.viewMode!==mode){this.viewMode=mode;this.reset()}}
 reset(){const id=this.drag?.id;this.drag=null;this.suppressClick=true;this.canvas.classList.remove('dragging');if(id!==undefined&&this.canvas.hasPointerCapture(id))this.canvas.releasePointerCapture(id);this.zoom=1;this.pan=[0,0];this.camera={...DEFAULT_CAMERA};this.draw()}
 update(data){this.data=data;this.draw()}
 draw(){const el=this.canvas,c=this.ctx,box=el.getBoundingClientRect(),w=box.width,h=box.height,dpr=window.devicePixelRatio||1;if(!w||!h)return;if(el.width!==Math.round(w*dpr)||el.height!==Math.round(h*dpr)){el.width=w*dpr;el.height=h*dpr}c.setTransform(dpr,0,0,dpr,0,0);c.clearRect(0,0,w,h);c.fillStyle='#f1f5f7';c.fillRect(0,0,w,h);this.hit=[];this.linkHit=[];if(!this.data?.scene)return;if(this.viewMode==='3d'){render3D(this,{width:w,height:h,positionAt});return}const {scene,position,positions=[],frame,decision,completedDecision,time:t,selectedNode,selectedPeer,event,layers,motionStep=3}=this.data;const bounds=scene.bounds;if(!Array.isArray(bounds)||bounds.length!==4)return;const [xmin,ymin,xmax,ymax]=bounds;const scale=Math.min((w-90)/(xmax-xmin),(h-75)/(ymax-ymin))*this.zoom;const X=x=>w/2+(x-(xmin+xmax)/2)*scale+this.pan[0],Y=y=>h/2-(y-(ymin+ymax)/2)*scale+this.pan[1];const nice=10**Math.floor(Math.log10(Math.max(xmax-xmin,ymax-ymin)/8));const grid=nice*(Math.max(xmax-xmin,ymax-ymin)/nice/8>2?2:1);c.strokeStyle='#e2e9ed';c.lineWidth=.6;for(let x=Math.ceil(xmin/grid)*grid;x<=xmax;x+=grid){c.beginPath();c.moveTo(X(x),Y(ymin));c.lineTo(X(x),Y(ymax));c.stroke()}for(let y=Math.ceil(ymin/grid)*grid;y<=ymax;y+=grid){c.beginPath();c.moveTo(X(xmin),Y(y));c.lineTo(X(xmax),Y(y));c.stroke()}c.strokeStyle='#bccbd4';c.setLineDash([3,4]);c.strokeRect(X(xmin),Y(ymax),(xmax-xmin)*scale,(ymax-ymin)*scale);c.setLineDash([]);
 for(const building of scene.buildings||[]){for(const rings of polygons(building.geometry)){c.beginPath();for(const ring of rings){ring.forEach((p,i)=>i?c.lineTo(X(p[0]),Y(p[1])):c.moveTo(X(p[0]),Y(p[1])));c.closePath()}c.fillStyle=finite(building.height_m)?'#d6dfe5':'#ecf0f3';c.fill('evenodd');c.strokeStyle='#b5c3cd';c.lineWidth=.8;c.stroke();if(building.imputed||!finite(building.height_m)){c.save();c.clip('evenodd');c.strokeStyle='#b1bec855';c.lineWidth=.65;for(let x=-h;x<w+h;x+=7){c.beginPath();c.moveTo(x,0);c.lineTo(x+h,h);c.stroke()}c.restore()}}}
 for(const zone of scene.no_fly_zones||[]){for(const rings of polygons(zone.geometry||zone.geometry_local_m||zone)){c.beginPath();for(const ring of rings){ring.forEach((p,i)=>i?c.lineTo(X(p[0]),Y(p[1])):c.moveTo(X(p[0]),Y(p[1])));c.closePath()}c.fillStyle='#d88e9415';c.fill('evenodd');c.strokeStyle='#bd747a77';c.setLineDash([3,4]);c.stroke();c.setLineDash([])}}
 const nodes=position?.uavs||[],nodeMap=new Map(nodes.map(n=>[n.id,n]));if(layers.tracks){for(const n of nodes){c.beginPath();let first=true;for(const p of positions){if(!layers.future&&p.sample_time_s>t)break;const u=p.uavs.find(u=>u.id===n.id);if(!u)continue;if(first){c.moveTo(X(u.x),Y(u.y));first=false}else c.lineTo(X(u.x),Y(u.y))}if(!layers.future)c.lineTo(X(n.x),Y(n.y));c.strokeStyle=n.id===selectedNode?'#25637baa':n.role==='search'?'#0d938d45':'#193b5a30';c.lineWidth=n.id===selectedNode?1.9:1;c.setLineDash(layers.future?[4,3]:[]);c.stroke();c.setLineDash([])}}
 if(layers.links&&frame){for(const l of frame.links||[]){const a=nodeMap.get(l.source),b=nodeMap.get(l.target);if(!a||!b)continue;const selected=(l.source===selectedNode&&l.target===selectedPeer)||(l.target===selectedNode&&l.source===selectedPeer);const related=event?.related_link_ids?.includes(l.id);if(!l.available&&!selected&&!related)continue;const aa=[X(a.x),Y(a.y)],bb=[X(b.x),Y(b.y)];c.beginPath();c.moveTo(...aa);c.lineTo(...bb);c.strokeStyle=l.available?(selected?'#087c75':'#5ea7a166'):'#c95b65';c.lineWidth=selected?2.5:related?2:1.2;c.setLineDash(l.available?[]:[5,4]);c.stroke();c.setLineDash([]);this.linkHit.push({...l,a:aa,b:bb})}}
 if(layers.actions&&decision){const base=positionAt(positions,decision.decision_time_s);for(const a of decision.actions||[]){const n=base.uavs.find(n=>n.id===a.uav_id);if(!n)continue;const chosen=a.uav_id===selectedNode;const vectors=[['requested_correction','#ca893a',true],['applied_correction','#8964b0',false]];if(layers.future)vectors.push(['actual_displacement','#24485f',false]);for(const [key,color,dashed] of vectors){const v=a[key];if(!Array.isArray(v)||v.length<2||Math.hypot(...v)<.01)continue;arrow(c,[X(n.x),Y(n.y)],[X(n.x+v[0]),Y(n.y+v[1])],color,chosen?2.1:1.3,dashed)}}}
 if(layers.actions&&completedDecision&&!layers.future){const base=positionAt(positions,completedDecision.decision_time_s);for(const a of completedDecision.actions||[]){const n=base.uavs.find(n=>n.id===a.uav_id),v=a.actual_displacement;if(!n||!Array.isArray(v)||Math.hypot(...v)<.01)continue;arrow(c,[X(n.x),Y(n.y)],[X(n.x+v[0]),Y(n.y+v[1])],'#24485f',a.uav_id===selectedNode?2.2:1.4,false)}}

 if(event?.marker){const marker=event.marker,xy=marker.position||marker.xy||(finite(marker.x)?[marker.x,marker.y]:null);if(xy){c.beginPath();c.arc(X(xy[0]),Y(xy[1]),19,0,2*Math.PI);c.strokeStyle='#cb5c6188';c.setLineDash([3,3]);c.stroke();c.setLineDash([])}}
 for(const n of nodes){const x=X(n.x),y=Y(n.y),selected=n.id===selectedNode,related=event?.related_uav_ids?.includes(n.id),color=aircraftPaint(this.data.communication,n.id).color;if(selected||related){c.beginPath();c.arc(x,y,selected?15:12,0,2*Math.PI);c.fillStyle=selected?'#0d938d1a':'#d9686d14';c.fill();c.strokeStyle=selected?'#0d938d99':'#cf6c7499';c.lineWidth=1;c.stroke()}c.beginPath();c.arc(x,y,5.5,0,2*Math.PI);c.fillStyle=color;c.fill();c.strokeStyle='#fff';c.lineWidth=2;c.stroke();c.fillStyle='#284458';c.font='bold 11px system-ui';c.textAlign='center';c.lineWidth=3;c.strokeStyle='#ffffff';const label=droneMapLabel(n.id,nodes);c.strokeText(label,x,y-10);c.fillText(label,x,y-10);this.hit.push({id:n.id,x,y})}
 const scaleEl=document.getElementById('mapScale');if(scaleEl){const bar=metricScaleBar(scale);scaleEl.style.width=`${bar.pixels}px`;scaleEl.textContent=`${num(bar.metres,6)} m`} }
}
function arrow(c,a,b,color,width,dash){const angle=Math.atan2(b[1]-a[1],b[0]-a[0]);c.beginPath();c.moveTo(...a);c.lineTo(...b);c.strokeStyle=color;c.lineWidth=width;c.setLineDash(dash?[4,3]:[]);c.stroke();c.setLineDash([]);c.beginPath();c.moveTo(...b);c.lineTo(b[0]-6*Math.cos(angle-.45),b[1]-6*Math.sin(angle-.45));c.lineTo(b[0]-6*Math.cos(angle+.45),b[1]-6*Math.sin(angle+.45));c.closePath();c.fillStyle=color;c.fill()}
function segmentDistance(p,a,b){const dx=b[0]-a[0],dy=b[1]-a[1],q=Math.max(0,Math.min(1,((p[0]-a[0])*dx+(p[1]-a[1])*dy)/(dx*dx+dy*dy||1)));return Math.hypot(p[0]-a[0]-q*dx,p[1]-a[1]-q*dy)}

export function eventIsCensored(event){return event?.temporal_kind!=='instant'&&(event?.right_censored===true||event?.end_s===null)}
export function eventEndText(event){
 if(event?.temporal_kind==='instant')return '순간 사건';
 if(eventIsCensored(event)){const outage=event.scope==='search_network'||String(event.type||'').includes('outage');return (outage?'회복 미관측':'종료 미관측')+' · 종료 검열'+(finite(event.end_s)?' · 관측 종료 '+num(event.end_s,1)+' s':'')}
 return finite(event?.end_s)?'종료 '+num(event.end_s,1)+' s':'종료 시각 미기록';
}
export function eventAfterTime(event,duration,rfStep=.5,motionStep=3){
 if(eventIsCensored(event))return null;
 if(event?.type==='intervention')return Math.min(duration,event.outcome_available_at_s??event.start_s+motionStep);
 if(event?.temporal_kind==='instant')return Math.min(duration,event.start_s+rfStep);
 return finite(event?.end_s)?Math.min(duration,event.end_s):null;
}
